package cn.bidcheck.ocr;

import java.util.*;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.ocr.OcrLayout.*;
import static cn.bidcheck.ocr.GridLayoutAssembler.*;
import static org.junit.jupiter.api.Assertions.*;

class GridLayoutAssemblerTest {
    final GridLayoutAssembler assembler=new GridLayoutAssembler();
    final String text="姓名 月份\n合成甲 2025-01";
    final Frame frame=new Frame("f",200,100,cn.bidcheck.compat.Java8Api.repeat("a", 64),"PDF_PAGE",1,null,null,null);
    OcrLayout base(){return new OcrLayout(OcrLayout.VERSION,"COMPLETE",COORDINATES,cn.bidcheck.compat.Java8Api.listOf(frame),cn.bidcheck.compat.Java8Api.listOf(new TextBox("b1","f","姓名",new Box(10,10,30,10),null), new TextBox("b2","f","月份",new Box(110,10,30,10),.8), new TextBox("b3","f","合成甲",new Box(10,60,30,10),.9), new TextBox("b4","f","2025-01",new Box(110,60,70,10),null)),cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf("b1", "b2", "b3", "b4"),cn.bidcheck.compat.Java8Api.listOf()).validated(text);}
    Region cell(int row,int col,double x1,double y1,double x2,double y2,boolean header){return new Region(row,col,1,1,cn.bidcheck.compat.Java8Api.listOf(x1, y1, x2, y2),header);}
    Grid grid(){return new Grid("f",PIXEL_XYXY,2,2,cn.bidcheck.compat.Java8Api.listOf(cell(0,0,0,0,100,50,true), cell(0,1,100,0,200,50,true), cell(1,0,0,50,100,100,false), cell(1,1,100,50,200,100,false)));}
    Set<String> codes(Assembly result){return new HashSet<>(cn.bidcheck.compat.Java8Api.toList(result.diagnostics().stream().map(Diagnostic::code)));}
    @Test void serverGeneratesTextReferencesHeadersAndStableIds(){cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(grid()));assertEquals("COMPLETE",result.layout().status());assertTrue(result.diagnostics().isEmpty());java.util.List<cn.bidcheck.ocr.OcrLayout.Cell> cells=result.layout().tables().get(0).cells();assertEquals("合成甲",cells.get(2).text());assertEquals(cn.bidcheck.compat.Java8Api.listOf("b3"),cells.get(2).blockIds());assertEquals(cn.bidcheck.compat.Java8Api.listOf(cells.get(0).id()),cells.get(2).headerCellIds());assertNull(result.layout().textBoxes().get(0).confidence());assertEquals(.8,result.layout().textBoxes().get(1).confidence());java.util.ArrayList<cn.bidcheck.ocr.GridLayoutAssembler.Region> reverse=new ArrayList<>(grid().cells());Collections.reverse(reverse);assertEquals(result.layout().tables(),assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,2,2,reverse))).layout().tables());}
    @Test void explicitlyNormalizedCoordinatesConvertToTheSubmittedImageAndSameStableGrid(){java.util.List<cn.bidcheck.ocr.GridLayoutAssembler.Region> normalized=cn.bidcheck.compat.Java8Api.toList(grid().cells().stream().map(c->new Region(c.row(),c.column(),c.rowSpan(),c.columnSpan(),cn.bidcheck.compat.Java8Api.listOf(c.box().get(0)*5, c.box().get(1)*10, c.box().get(2)*5, c.box().get(3)*10),c.header())));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f",NORMALIZED_1000_XYXY,2,2,normalized)));assertTrue(result.diagnostics().isEmpty());assertEquals(assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(grid())).layout().tables(),result.layout().tables());}
    @Test void unknownCoordinateSpaceIsNeverGuessed(){cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f","AUTO",2,2,grid().cells())));assertTrue(codes(result).contains("GRID_COORDINATE_SPACE_UNSUPPORTED"));assertEquals("PARTIAL",result.layout().status());assertEquals(base().textBoxes(),result.layout().textBoxes());assertTrue(result.layout().tables().isEmpty());}
    @Test void normalizedLookingValuesDeclaredPixelsAreRejectedInsteadOfRescaled(){cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,1,1,cn.bidcheck.compat.Java8Api.listOf(cell(0,0,0,0,1000,1000,false)))));assertTrue(codes(result).contains("GRID_COORDINATES_OUT_OF_BOUNDS"));}
    @Test void unknownInputTextCoordinateSpaceFailsRatherThanBeingSilentlyReinterpreted(){cn.bidcheck.ocr.OcrLayout b=base();cn.bidcheck.ocr.OcrLayout unknown=new OcrLayout(b.schemaVersion(),b.status(),"UNKNOWN",b.frames(),b.textBoxes(),b.tables(),b.readingOrder(),b.warnings());assertThrows(IllegalArgumentException.class,()->assembler.assemble(unknown,text,cn.bidcheck.compat.Java8Api.listOf(grid())));}
    @Test void crossingTextBoxRejectsOnlyItsTableAndRetainsAllIndependentText(){cn.bidcheck.ocr.OcrLayout b=base();java.util.ArrayList<cn.bidcheck.ocr.OcrLayout.TextBox> boxes=new ArrayList<>(b.textBoxes());boxes.set(0,new TextBox("b1","f","姓名",new Box(90,10,20,10),null));cn.bidcheck.ocr.OcrLayout crossed=new OcrLayout(b.schemaVersion(),b.status(),b.coordinateSystem(),b.frames(),boxes,cn.bidcheck.compat.Java8Api.listOf(),b.readingOrder(),b.warnings());cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(crossed,text,cn.bidcheck.compat.Java8Api.listOf(grid()));assertTrue(codes(result).contains("GRID_TEXT_CROSSES_CELL_BOUNDARY"));assertEquals(boxes,result.layout().textBoxes());assertTrue(result.layout().tables().isEmpty());}
    @Test void logicallyDifferentButGeometricallyOverlappingCellsAreRejected(){java.util.ArrayList<cn.bidcheck.ocr.GridLayoutAssembler.Region> cells=new ArrayList<>(grid().cells());cells.set(0,cell(0,0,0,0,120,50,true));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(codes(result).contains("GRID_CELL_GEOMETRY_OVERLAP"));}
    @Test void duplicateLogicalCellsCannotCreateMultipleOwnership(){java.util.ArrayList<cn.bidcheck.ocr.GridLayoutAssembler.Region> cells=new ArrayList<>(grid().cells());cells.set(1,cell(0,0,100,0,200,50,true));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(codes(result).contains("GRID_LOGICAL_OVERLAP"));}
    @Test void missingLogicalCellsAreExplicitlyPartial(){cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,2,2,grid().cells().subList(0,3))));assertTrue(codes(result).contains("GRID_LOGICAL_COVERAGE_INCOMPLETE"));assertEquals("PARTIAL",result.layout().status());}
    @Test void oneBadGridDoesNotEraseAnotherValidTable(){cn.bidcheck.ocr.GridLayoutAssembler.Grid left=new Grid("f",PIXEL_XYXY,2,1,cn.bidcheck.compat.Java8Api.listOf(cell(0,0,0,0,100,50,true), cell(1,0,0,50,100,100,false)));cn.bidcheck.ocr.GridLayoutAssembler.Grid bad=new Grid("f","UNSPECIFIED",2,1,cn.bidcheck.compat.Java8Api.listOf(cell(0,0,100,0,200,50,true), cell(1,0,100,50,200,100,false)));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(left, bad));assertEquals(1,result.layout().tables().size());assertEquals("合成甲",result.layout().tables().get(0).cells().get(1).text());assertEquals(4,result.layout().textBoxes().size());assertEquals("PARTIAL",result.layout().status());}
    @Test void overlappingTablesAreBothRejectedInsteadOfFirstWinning(){cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(grid(), grid()));assertTrue(result.layout().tables().isEmpty());assertEquals(2,result.diagnostics().stream().filter(d->d.code().equals("GRID_TABLES_OVERLAP")).count());assertEquals(4,result.layout().textBoxes().size());}
    @Test void mergedCellsJoinOriginalBoxesInValidatedReadingOrder(){cn.bidcheck.ocr.GridLayoutAssembler.Grid merged=new Grid("f",PIXEL_XYXY,2,2,cn.bidcheck.compat.Java8Api.listOf(new Region(0,0,1,2,cn.bidcheck.compat.Java8Api.listOf(0d, 0d, 200d, 50d),true), cell(1,0,0,50,100,100,false), cell(1,1,100,50,200,100,false)));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(merged));assertTrue(result.diagnostics().isEmpty());java.util.List<cn.bidcheck.ocr.OcrLayout.Cell> cells=result.layout().tables().get(0).cells();assertEquals("姓名\n月份",cells.get(0).text());assertEquals(cn.bidcheck.compat.Java8Api.listOf("b1", "b2"),cells.get(0).blockIds());assertEquals(cn.bidcheck.compat.Java8Api.listOf(cells.get(0).id()),cells.get(2).headerCellIds());}
    @Test void twoExactSourceLabelsCanIdentifyHeadersWithoutModelFlags(){java.util.List<cn.bidcheck.ocr.GridLayoutAssembler.Region> cells=cn.bidcheck.compat.Java8Api.toList(grid().cells().stream().map(c->new Region(c.row(),c.column(),1,1,c.box(),false)));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,2,2,cells)));java.util.List<cn.bidcheck.ocr.OcrLayout.Cell> actual=result.layout().tables().get(0).cells();assertTrue(actual.get(0).header());assertTrue(actual.get(1).header());assertFalse(actual.get(2).header());assertEquals(cn.bidcheck.compat.Java8Api.listOf(actual.get(0).id()),actual.get(2).headerCellIds());}
    @Test void oneExactLabelDoesNotPromoteAnEntireRow(){cn.bidcheck.ocr.OcrLayout b=base();java.util.ArrayList<cn.bidcheck.ocr.OcrLayout.TextBox> boxes=new ArrayList<>(b.textBoxes());boxes.set(1,new TextBox("b2","f","备注内容",boxes.get(1).bbox(),null));cn.bidcheck.ocr.OcrLayout changed=new OcrLayout(b.schemaVersion(),b.status(),b.coordinateSystem(),b.frames(),boxes,cn.bidcheck.compat.Java8Api.listOf(),b.readingOrder(),cn.bidcheck.compat.Java8Api.listOf());java.util.List<cn.bidcheck.ocr.GridLayoutAssembler.Region> cells=cn.bidcheck.compat.Java8Api.toList(grid().cells().stream().map(c->new Region(c.row(),c.column(),1,1,c.box(),false)));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(changed,text.replace("月份","备注内容"),cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(result.layout().tables().get(0).cells().stream().noneMatch(Cell::header));}
    @Test void LabelSubstringsDoNotPromoteHeaders(){cn.bidcheck.ocr.OcrLayout b=base();java.util.ArrayList<cn.bidcheck.ocr.OcrLayout.TextBox> boxes=new ArrayList<>(b.textBoxes());boxes.set(0,new TextBox("b1","f","填写姓名",boxes.get(0).bbox(),null));boxes.set(1,new TextBox("b2","f","月份说明",boxes.get(1).bbox(),null));cn.bidcheck.ocr.OcrLayout changed=new OcrLayout(b.schemaVersion(),b.status(),b.coordinateSystem(),b.frames(),boxes,cn.bidcheck.compat.Java8Api.listOf(),b.readingOrder(),cn.bidcheck.compat.Java8Api.listOf());java.util.List<cn.bidcheck.ocr.GridLayoutAssembler.Region> cells=cn.bidcheck.compat.Java8Api.toList(grid().cells().stream().map(c->new Region(c.row(),c.column(),1,1,c.box(),false)));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(changed,text.replace("姓名","填写姓名").replace("月份","月份说明"),cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(result.layout().tables().get(0).cells().stream().noneMatch(Cell::header));}
    @Test void sameCoordinatesInAnotherFrameDoNotBorrowItsText(){cn.bidcheck.ocr.OcrLayout b=base();cn.bidcheck.ocr.OcrLayout.Frame other=new Frame("other",200,100,cn.bidcheck.compat.Java8Api.repeat("b", 64),"WORD_IMAGE",2,null,null,null);cn.bidcheck.ocr.OcrLayout multi=new OcrLayout(b.schemaVersion(),b.status(),b.coordinateSystem(),cn.bidcheck.compat.Java8Api.listOf(frame, other),b.textBoxes(),cn.bidcheck.compat.Java8Api.listOf(),b.readingOrder(),cn.bidcheck.compat.Java8Api.listOf());cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(multi,text,cn.bidcheck.compat.Java8Api.listOf(new Grid("other",PIXEL_XYXY,2,2,grid().cells())));assertTrue(codes(result).contains("GRID_WITHOUT_SOURCE_TEXT"));}
    @Test void invalidIndependentTranscriptionIsNeverRepairedByTheGrid(){assertThrows(IllegalArgumentException.class,()->assembler.assemble(base(),"姓名 月份 另一个人 2025-01",cn.bidcheck.compat.Java8Api.listOf(grid())));}
    @Test void inconsistentRowGeometryRetainsBoxesAndExplainsTheRejectedTable(){java.util.List<cn.bidcheck.ocr.GridLayoutAssembler.Region> cells=cn.bidcheck.compat.Java8Api.listOf(cell(1,0,0,0,100,50,false), cell(1,1,100,0,200,50,false), cell(0,0,0,50,100,100,true), cell(0,1,100,50,200,100,true));cn.bidcheck.ocr.GridLayoutAssembler.Assembly result=assembler.assemble(base(),text,cn.bidcheck.compat.Java8Api.listOf(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(codes(result).contains("GRID_LAYOUT_VALIDATION_FAILED"));assertEquals(4,result.layout().textBoxes().size());}
}
